mapper.select:
SELECT  FROM aftersales_case WHERE tenant_id=#{tenant} AND member_id=#{member} AND case_id>#{after}
    AND order_id=#{filter.orderId}
    AND business_no=#{filter.q}AND (LOCATE(#{filter.q},case_id)>0 OR LOCATE(#{filter.q},order_id)>0 OR LOCATE(#{filter.q},member_id)>0)
    AND status=#{filter.status} ORDER BY case_id LIMIT #{limit}

SELECT ,o.store_id,a.created_at,a.business_no  AND a.case_id>#{after}
    AND o.store_id=#{filter.storeId}
    AND a.order_id=#{filter.orderId}
    AND a.business_no=#{filter.q}AND (LOCATE(#{filter.q},a.case_id)>0 OR LOCATE(#{filter.q},a.order_id)>0 OR LOCATE(#{filter.q},a.member_id)>0 OR LOCATE(#{filter.q},a.refund_id)>0)
    AND a.status=#{filter.status} ORDER BY a.case_id LIMIT #{limit}
